   const received=await(await request(config.proposalEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId:intent.requestId,fragment:intent.fragment,note:intent.note,sourceUrl:'https://jelliottdev.github.io/run.html#idea='+id}),...(signal?{signal}:{})})).json();if(!isCurrent())return null;
